const ALWAYS = new Set(['index.html', 'app.js']);
const MANIFEST = '__ke_manifest__';
// Onceki surumun onbellegi + parmak izleri: degismeyen dosya oradan kopyalanir.
async function previous() {
  for (const k of await caches.keys()) {
    if (k === V || !k.startsWith('ke-')) continue;
    const old = await caches.open(k);
    const m = await old.match(MANIFEST);
    if (m) { try { return { cache: old, hashes: (await m.json()).hashes || {} }; } catch (err) { /* bozuk */ } }
  }
  return null;
}
async function reuse(c, prev, u) {
  if (!prev || ALWAYS.has(u) || !HASHES[u] || prev.hashes[u] !== HASHES[u]) return false;
  const hit = await prev.cache.match(u);
  if (!hit) return false;
  await c.put(u, hit);
  return true;
}
self.addEventListener('install', (e) => {
  e.waitUntil((async () => {
    const c = await caches.open(V);
    const prev = await previous();
    await c.put('__ke_total__', new Response(String(new Set(CORE.concat(LAZY)).size)));
    await Promise.all(CORE.map(async (u) => { if (!(await reuse(c, prev, u))) await c.add(u).catch(() => {}); }));
    self.skipWaiting();
    await fillLazy(c, prev);
    await c.put(MANIFEST, new Response(JSON.stringify({ v: V, hashes: HASHES }), { headers: { 'Content-Type': 'application/json' } }));
  })());
});
async function fillLazy(c, prev) {
  let todo = LAZY.slice();
  for (let round = 0; round < 3 && todo.length; round++) {
    const failed = [];
    for (let i = 0; i < todo.length; i += 12) {
      let fetched = false;
      await Promise.all(todo.slice(i, i + 12).map(async (u) => {
        if (await c.match(u)) return;
        if (await reuse(c, prev, u)) return;
        fetched = true;
        try { const r = await fetch(u); if (r.ok) await c.put(u, r); else failed.push(u); } catch (err) { failed.push(u); }
      }));
      if (fetched) await new Promise((r) => setTimeout(r, 120)); // yalniz agdan indirirken nefes payi
    }
    todo = failed;
    if (todo.length) await new Promise((r) => setTimeout(r, 2000));
  }
}
self.addEventListener('activate', (e) => {
  e.waitUntil((async () => {
    for (const k of await caches.keys()) if (k !== V) await caches.delete(k);
    await self.clients.claim();
  })());
});
// CORE yollarini SW'nin kendi konumuna (uygulama kokune, alt-yol ne
// olursa olsun) gore MUTLAK URL'e ceviriyoruz - boylece istegin tam
// r.url'i ile dogrudan karsilastirilabiliyor (yol-onek varsayimi yok).
const CORE_SET = new Set(CORE.map((u) => new URL(u, location.href).href));
self.addEventListener('fetch', (e) => {
  const r = e.request;
  if (r.method !== 'GET' || new URL(r.url).origin !== location.origin) return;
  // CORE dosyalari (uygulama mantigi + veri: index/app.js/panel.js/
  // episodes.json) her zaman ONCE AGDAN denenir - "her guncellemede
  // onbellek temizlemek gerekiyor" sorununun asil kokeni buydu (eskiden
  // hepsi once-onbellek'ti, ag hic denenmiyordu). Cevrimdisiyken ya da ag
  // hata verirse en son onbellege dusuyor. Fotograf/ikon gibi LAZY
  // varliklar hala once-onbellek (hizli + zaten seyrek degisiyor).
  const isCore = r.mode === 'navigate' || CORE_SET.has(r.url);
  e.respondWith((async () => {
    if (isCore) {
      try {
        const res = await fetch(r, { cache: 'no-store' });
        if (res.ok) (await caches.open(V)).put(r, res.clone());
        return res;
      } catch (err) {
        return (await caches.match(r, { ignoreSearch: true })) || (await caches.match('index.html')) || Response.error();
      }
    }
    const hit = await caches.match(r, { ignoreSearch: true });
    if (hit) return hit;
    try {
      const res = await fetch(r);
      if (res.ok) (await caches.open(V)).put(r, res.clone());
      return res;
    } catch (err) {
      return Response.error();
    }
  })());
});
